import React, { useState, useEffect } from 'react';
import './PostForm.css';

function PostForm({ onSubmit, onUpdate, editingPost, onCancel, loading }) {
  const [title, setTitle] = useState('');
  const [author, setAuthor] = useState('');
  const [publishedDate, setPublishedDate] = useState(
    new Date().toISOString().split('T')[0]
  );
  const [content, setContent] = useState('');

  // If editingPost changes, populate the form inputs
  useEffect(() => {
    if (editingPost) {
      setTitle(editingPost.title || '');
      setAuthor(editingPost.author || '');
      setPublishedDate(
        editingPost.publishedDate
          ? new Date(editingPost.publishedDate).toISOString().split('T')[0]
          : ''
      );
      setContent(editingPost.content || '');
    } else {
      setTitle('');
      setAuthor('');
      setPublishedDate(new Date().toISOString().split('T')[0]);
      setContent('');
    }
  }, [editingPost]);

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!title || !author || !content) {
      alert('Please fill in all fields.');
      return;
    }

    const postData = { title, author, publishedDate, content };

    if (editingPost) {
      onUpdate(editingPost._id, postData);
    } else {
      onSubmit(postData);
      setTitle('');
      setAuthor('');
      setContent('');
    }
  };

  return (
    <div className="card shadow-sm">
      <div className="card-header bg-white">
        <h5 className="mb-0 text-primary fw-bold">
          {editingPost ? 'Edit Post' : 'Create New Post'}
        </h5>
      </div>
      <div className="card-body">
        <form onSubmit={handleSubmit}>
          {/* Title */}
          <div className="mb-3">
            <label className="form-label fw-bold">Title</label>
            <input
              type="text"
              className="form-control"
              placeholder="Enter title"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              required
            />
          </div>

          {/* Author */}
          <div className="mb-3">
            <label className="form-label fw-bold">Author</label>
            <input
              type="text"
              className="form-control"
              placeholder="Enter author name"
              value={author}
              onChange={(e) => setAuthor(e.target.value)}
              required
            />
          </div>

          {/* Published Date */}
          <div className="mb-3">
            <label className="form-label fw-bold">Published Date</label>
            <input
              type="date"
              className="form-control"
              value={publishedDate}
              onChange={(e) => setPublishedDate(e.target.value)}
              required
            />
          </div>

          {/* Content */}
          <div className="mb-3">
            <label className="form-label fw-bold">Content</label>
            <textarea
              className="form-control"
              rows="5"
              placeholder="Write content here..."
              value={content}
              onChange={(e) => setContent(e.target.value)}
              required
            ></textarea>
          </div>

          {/* Buttons */}
          <div className="d-flex gap-2">
            <button type="submit" className="btn btn-primary" disabled={loading}>
              {editingPost ? 'Update Post' : 'Publish Post'}
            </button>
            {editingPost && (
              <button
                type="button"
                className="btn btn-secondary"
                onClick={onCancel}
              >
                Cancel
              </button>
            )}
          </div>
        </form>
      </div>
    </div>
  );
}

export default PostForm;
